//! Original model-owned enum equality: admitted by QSL and IR, derived and generated by CG, and
//! agreeing with QSL's checked body on the typed result, ordered charges, denied points and counters.

#[path = "support/family_function_selection.rs"]
mod family_function_selection;
#[path = "support/family_scalar_limits.rs"]
mod family_scalar_limits;
#[allow(dead_code)]
#[path = "support/generated_oracle.rs"]
mod generated_oracle;
#[allow(dead_code)]
#[path = "support/oracle_observation.rs"]
mod oracle_observation;

use ix_trace_rs::trace;
use qsl_semantics::{
    check::PackageDeclarations,
    model::{
        accounting::ModelNormalizationLimits,
        intake::{admit_unit, package_input},
    },
};
use quire_contract_codegen::{
    derive_exact_scalar_items, generate_exact_scalar_oracles, ClaimDisposition,
    ExactScalarOperation,
};
use quire_contract_ir::{
    CheckedNodeId, CheckedPackageEvidence, CheckedPackageReadLimits, CheckedPackageV2,
    CheckedPackageV2ReadResult, CheckedTerm,
};
use quire_eval::FamilyOutcome;
use quire_exact::{LimitKind, Meter, Outcome, Value};
use quire_semantic_value::checking::CheckingLimits;
use quire_specification::{ACME_COLORS_COMPARISON_SOURCE, ACME_COLORS_DOMAIN_PACKAGE};

/// Work allowances: ample, exhausted before the first charge, and exhausted after one to three
/// admitted charges.
const WORK: [u64; 5] = [1024, 0, 1, 2, 3];

/// Host-side reconstruction of the genuine `Red` and `Green` members, run inside the generated
/// crate's driver so the generated oracle receives the same model members QSL evaluates.
const MEMBERS: &str = r#"
fn colors(source: &str, document: &str) -> std::collections::BTreeMap<String, quire_semantic_value::enumeration::EnumValue> {
    let compiled = qsl_replay::compile_admitted(
        qsl_replay::CompileUnit { source: qsl_replay::SourceIdentity::new("agent-ix", "enum-comparison"), package_name: "agent-ix/enum-comparison".to_owned(), path: "enum-comparison.native", bytes: source.as_bytes() },
        [document.as_bytes()], &qsl_replay::DependencyInput::default(), qsl_replay::StageLimits::default(), qsl_replay::ReplayLimits::default(),
    ).expect("original colors source compiles");
    let wire: serde_json::Value = serde_json::from_slice(compiled.package().bytes()).expect("emission JSON");
    let mut evidence = quire_contract_model::CheckedPackageEvidence::new();
    for feature in wire["lock"]["required_features"].as_array().expect("features") { evidence.support_feature(feature.as_str().expect("feature")); }
    evidence.insert_domain_package_document("acme/colors", document.as_bytes()).expect("colors evidence");
    let quire_contract_model::CheckedPackageV2ReadResult::Admitted(package) = quire_contract_model::CheckedPackageV2::read(compiled.package().bytes(), quire_contract_model::CheckedPackageReadLimits::bounded(), &evidence) else { panic!("enum package admits"); };
    let term_data = package.checked_term_data().expect("term data");
    let mut witnesses = std::collections::BTreeMap::new();
    for decision in &term_data.equality_decisions { for member in &decision.enum_members { witnesses.insert(member.case.to_string(), member); } }
    let first = witnesses["Red"];
    let declared = package.resolved_graph().nodes.iter().find(|node| node.node_id == first.enum_type).expect("enum declaration");
    let graph = compiled.context().wire_graph();
    let declaration = quire_semantic_value::enumeration::EnumDeclaration::new(graph.key(&declared.node_id).expect("declaration key"), false, witnesses.keys().cloned().collect()).expect("declaration");
    witnesses.into_iter().map(|(case, witness)| { let value = declaration.member(&case, graph.key(&witness.member).expect("member key")).expect("member"); (case, value) }).collect()
}
"#;

#[trace("TC-102", "IT-019-SC-05")]
#[test]
fn model_owned_enum_equality_agrees_with_the_generated_oracle() {
    let document = ACME_COLORS_DOMAIN_PACKAGE.as_bytes();
    let parsed = qsl_cst::parse(
        qsl_foundation::SourceIdentity::new("agent-ix", "enum-comparison"),
        "enum-comparison.native",
        ACME_COLORS_COMPARISON_SOURCE.as_bytes(),
        qsl_cst::Limits::default(),
    )
    .expect("the QSpec native source parses");
    assert!(parsed.is_admissible(), "{:?}", parsed.diagnostics());
    let raw = parsed.source().reference().clone();
    let unit = qsl_forms::build_unit(&parsed).expect("the native source forms");
    let models = admit_unit(
        &unit.selections().models,
        &package_input([document]).expect("the colors model has its declared identity"),
        ModelNormalizationLimits::default(),
    )
    .expect("the QSpec colors model admits");
    let graph = PackageDeclarations::assemble(
        raw,
        "agent-ix/enum-comparison".to_owned(),
        unit,
        models,
        Vec::new(),
    )
    .expect("the unit assembles")
    .check(CheckingLimits::default())
    .expect("the unit checks");
    let package = qsl_package::CheckedPackage::link(graph);
    let emission = qsl_package::emit_checked(
        &package,
        qsl_package::EmitLimits::new(qsl_replay::spine::EMIT_OUTPUT_BYTES_DEFAULT),
    )
    .expect("the package emits");
    assert!(emission.omitted().is_empty());
    let wire: serde_json::Value =
        serde_json::from_slice(emission.package().bytes()).expect("emitted JSON");
    let mut evidence = CheckedPackageEvidence::new();
    for feature in wire["lock"]["required_features"]
        .as_array()
        .expect("features")
    {
        evidence.support_feature(feature.as_str().expect("feature"));
    }
    evidence
        .insert_domain_package_document("acme/colors", document)
        .expect("the colors model is valid evidence");
    let CheckedPackageV2ReadResult::Admitted(admitted) = CheckedPackageV2::read(
        emission.package().bytes(),
        CheckedPackageReadLimits::bounded(),
        &evidence,
    ) else {
        panic!("the emitted enum package admits");
    };
    let functions = [
        ("redEqualsRed", "Red", true),
        ("redEqualsGreen", "Green", false),
        ("redDiffersFromRed", "Red", false),
        ("redDiffersFromGreen", "Green", true),
    ];
    let nodes = functions
        .iter()
        .map(|(name, _, _)| family_function_selection::body(&admitted, name))
        .collect::<Vec<_>>();
    let items = derive_exact_scalar_items(&admitted, &nodes)
        .into_iter()
        .zip(functions)
        .zip([
            quire_exact::ComparisonOperator::Equal,
            quire_exact::ComparisonOperator::Equal,
            quire_exact::ComparisonOperator::NotEqual,
            quire_exact::ComparisonOperator::NotEqual,
        ])
        .map(|((derived, (name, _, _)), operator)| {
            let item = derived.unwrap_or_else(|error| panic!("{name}: CG derivation: {error:?}"));
            assert_eq!(
                item.operation,
                ExactScalarOperation::EnumComparison { operator }
            );
            let CheckedTerm::Application { operation, .. } = admitted
                .term(&item.node_id)
                .expect("original comparison body term")
            else {
                panic!("original enum comparison application");
            };
            assert_eq!(
                operation.identity(),
                Some(match operator {
                    quire_exact::ComparisonOperator::Equal => "quire.op.enum.eq",
                    _ => "quire.op.enum.ne",
                })
            );
            item
        })
        .collect::<Vec<_>>();
    let output = generate_exact_scalar_oracles(&admitted, &items)
        .expect("original enum comparisons generate");
    assert_eq!(output.claim_map.items.len(), functions.len());

    let mut expected = Vec::new();
    let mut driver = format!(
        r#"
mod oracle_observation;
use quire_exact::{{Meter, Outcome, ScalarLimits, Value}};
fn lift(outcome: Outcome<bool>) -> Outcome<Value> {{
    match outcome {{ Outcome::Completed(v) => Outcome::Completed(Value::Boolean(v)), Outcome::Undefined(v) => Outcome::Undefined(v), Outcome::Refused(v) => Outcome::Refused(v), Outcome::Incomplete(v) => Outcome::Incomplete(v) }}
}}
{MEMBERS}
#[test]
fn observe() {{
let members = colors({source:?}, {document:?});
let red = &members["Red"];
"#,
        source = ACME_COLORS_COMPARISON_SOURCE,
        document = ACME_COLORS_DOMAIN_PACKAGE,
    );
    for (index, (name, right, answer)) in functions.iter().enumerate() {
        let claims = output
            .claim_map
            .items
            .iter()
            .filter(|claim| claim.node_id == nodes[index])
            .collect::<Vec<_>>();
        let [claim] = claims.as_slice() else {
            panic!("one claim for {name}");
        };
        let ClaimDisposition::Generated(generated) = &claim.result else {
            panic!("{name} generates: {:?}", claim.result);
        };
        let function = package
            .graph()
            .function_by_identity(package.graph().function_identity(name).expect("identity"))
            .expect("original comparison body");
        for work in WORK {
            let mut meter = Meter::new(family_scalar_limits::limits(work));
            meter.enable_charge_capture(64, 256);
            let evaluation = qsl_eval::value::evaluate_closed_with_frame(
                &package,
                function.body,
                function.slots,
                Vec::new(),
                function.formed_units,
                &mut meter,
            )
            .expect("checked-body evaluation");
            assert!(evaluation.losses.is_empty());
            let FamilyOutcome::Evaluated(outcome) = evaluation.outcome else {
                panic!("QSL value family");
            };
            let capture = meter
                .take_charge_capture()
                .expect("capture enabled")
                .expect("complete capture");
            let (admitted_charges, denied) = oracle_observation::split(capture.events());
            if denied.is_empty() {
                // An allowance that covers every charge completes with the truth arm.
                assert!(
                    matches!(&outcome, Outcome::Completed(Value::Boolean(value)) if value == answer),
                    "{name} work={work}: {outcome:?}"
                );
                assert!(!admitted_charges.is_empty());
            } else {
                let Outcome::Incomplete(stop) = &outcome else {
                    panic!("{name} work={work} stops: {outcome:?}");
                };
                assert_eq!(stop.limit_kind, LimitKind::WorkUnits);
                assert_eq!(denied, vec![stop.charge_point]);
                assert!(admitted_charges.len() as u64 <= work);
            }
            if work == 1024 {
                assert!(denied.is_empty(), "{name}: ample allowance denies nothing");
            } else if work == 0 {
                assert_eq!(
                    denied.len(),
                    1,
                    "{name}: allowance 0 denies the first charge"
                );
            }
            expected.push(oracle_observation::ledger_snapshot(
                &outcome,
                &admitted_charges,
                &denied,
                &meter,
            ));
            driver.push_str(&format!(
                r#"
{{ let mut meter=Meter::new({allowance:?}); meter.enable_charge_capture(64,256);
let actual=lift(quire_exact_scalar_oracles::{oracle}(red,&members[{right:?}],&mut meter).expect("genuine members are valid input"));
let capture=meter.take_charge_capture().expect("capture enabled").expect("complete capture");
let (admitted,denied)=oracle_observation::split(capture.events());
println!("IT019_OBSERVATION {{}}",oracle_observation::ledger_snapshot(&actual,&admitted,&denied,&meter)); }}
"#,
                allowance = family_scalar_limits::limits(work),
                oracle = generated.symbol,
            ));
        }
    }
    driver.push_str("}\n");
    assert_eq!(expected.len(), 20, "four arms under five allowances");
    assert_eq!(
        generated_oracle::execute_with(
            &output.artifacts,
            &driver,
            concat!(
                "quire-eval = { git = \"https://github.com/agent-ix/quire-eval\", branch = \"main\", default-features = false }\n",
                "qsl-replay = { git = \"https://github.com/agent-ix/quire-spec-language\", branch = \"main\" }\n",
                "quire-contract-model = { git = \"https://github.com/agent-ix/quire-contract-ir\", branch = \"main\" }\n",
                "quire-semantic-value = { git = \"https://github.com/agent-ix/quire-semantic-value\", branch = \"main\" }\n",
                "serde_json = \"1\"\n",
            ),
        ),
        expected
    );
}
